import numpy as np, ot, random
from scipy.optimize import linear_sum_assignment

def matches(seed, n=600):
    random.seed(seed)
    np.random.seed(seed)
    a=ot.utils.unif(n)
    M=ot.dist(np.random.rand(n,2), np.random.rand(n,2))
    G1=ot.lp.emd(a,a,np.ascontiguousarray(M),check_marginals=False)
    row,col=linear_sum_assignment(M)
    G2=np.zeros_like(M); G2[row,col]=1.0/n
    return np.array_equal(G1,G2)
for seed in range(100):
    if not matches(seed,600):
        print('failure',seed)
        break
else:
    print('All 100 ok')
